package edu.gcu.cst339.lab2_chinook_api.track;

import java.math.BigDecimal;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for tracks.
 *
 * <p>The validation annotations are checked when a request body is marked
 * {@code @Valid} in the controller.</p>
 *
 * @param trackId      the track ID; generated by the database, so it is ignored
 *                     on create and taken from the URL on update
 * @param name         track name; required, at most 200 characters
 * @param albumId      ID of the album the track belongs to; optional
 * @param mediaTypeId  ID of the track's media type; required
 * @param genreId      ID of the track's genre; optional
 * @param composer     composer(s); optional, at most 220 characters
 * @param milliseconds length of the track in milliseconds; required
 * @param bytes        file size in bytes; optional
 * @param unitPrice    price of one purchase; required
 */
record TrackDto(
    Integer trackId,
    @NotNull @Size(max = 200) String name,   
    Integer albumId,
    @NotNull Integer mediaTypeId,
    Integer genreId,
    @Size(max = 220) String composer,
    @NotNull Integer milliseconds,
    Integer bytes,
    @NotNull BigDecimal unitPrice
) {
    /**
     * Converts a track entity into a DTO.
     *
     * @param track the entity to convert
     * @return a DTO containing all of the entity's fields
     */
    static TrackDto fromEntity(Track track) {
        return new TrackDto(
            track.getTrackId(),
            track.getName(),
            track.getAlbumId(),
            track.getMediaTypeId(),
            track.getGenreId(),
            track.getComposer(),
            track.getMilliseconds(),
            track.getBytes(),
            track.getUnitPrice()
        );
    }
}
